var e={"29268u":`RoboKit — ein Roboterauto bauen & simulieren`,qvztjl:`RoboKit — zum Anfang des Tutorials`,s42iv2:`academe.com.br (öffnet in einem neuen Tab)`,"16us7mj":`Sprache`,ktdb8o:`Einstellungen`,"198kuu7":`3D-Werkbank`,ia581p:`Animation`,j4z771:`Pause`,wlqobg:`Pause (Leertaste)`,h23ysv:`Wiedergabegeschwindigkeit`,r953rm:`Zoom`,"19blqjd":`Vergrößern`,"110wpq2":`Verkleinern`,q5w460:`Ansicht`,bldqt5:`Explosionsansicht (E)`,"44cnpg":`Verfolgeransicht: dem Auto von hinten folgen (C)`,"13epjbk":`Draufsicht-Karte der Testarena`,j4zjee:`Das ausgewählte Hindernis`,yq1vr3:`Der Mitte des Hindernisses, gemessen von der Mitte der Arena, wo das Auto startet und auf der Karte nach oben schaut`,"19kd62s":`Arena anpassen`,l1a70i:`Arena anpassen: Hindernisse verschieben, drehen und in der Größe ändern`,"15n0apn":`Letzte Änderung rückgängig machen (Ctrl+Z). Ctrl+Shift+Z stellt sie wieder her`,j4uzpn:`Die Arena im Originalzustand, mit dem Auto wieder am Start`,"84sbk0":`Arena so lassen, wie sie war (Esc)`,"1oy9vz":`Diese Arena verwenden: die 3D-Ansicht wird neu aufgebaut und die Simulation läuft weiter`,ium5z9:`Wie das Programm des Autos entscheidet`,vq0gg8:`Ablaufdiagramm schließen`,s2tc63:`Schließen (Esc)`,"13bjj4d":`Schalte das Auto auf Auto und sieh zu, wie es entscheidet`,gfubiu:`Wie das Programm entscheidet: Ablaufdiagramm öffnen`,"1gh0at8":`Schritte des Tutorials`,"61nq88":`Frühere Schritte`,ga5x9q:`Spätere Schritte`,"1v1ybkn":`Fahren`,"9anomo":`Vorwärts (W / ↑)`,bbake2:`Links drehen (A / ←)`,bfl95g:`Stopp (Leertaste)`,iseiwq:`Rechts drehen (D / →)`,"4o292l":`Rückwärts (S / ↓)`,"10qzszt":`Motordrehzahl`,"2yhdcy":`Fahrmodus`,"8m10x9":`Manuell (1)`,"1ogxhr7":`Hindernisvermeidung (2)`,"1i3ygcv":`Motoren abschalten (3)`,"1dlx0na":`Summer (B)`,isqcd9:`Servowinkel`,"29ulgm":`Serielle Ausgabe`,"1l0xxoj":`Schließen`,"2r1h4p":`Verbindung`,cwepyb:`Wird geladen…`,"10iu545":`RoboKit braucht JavaScript.`,"120y7gz":`Gestaltet von`,"1hpelzf":`Board`,"1j2fqe6":`WERKBANK`,"17d8vhd":`Schritt 1 · Teile bereitlegen`,gqo5v1:`Simulator`,"1py6ulk":`Zum Untersuchen klicken`,"1ms3o1u":`Abstand`,"2w2xwg":`Tempo`,n44ilu:`Modus`,"1d2vfr6":`Servo`,"152va0w":`Simulation pausiert`,"11i7yk1":`Klicke auf ein Hindernis, um es auszuwählen.`,"1a4x3zw":`Größe`,"1kpdcfp":`Länge`,gfxz9b:`Breite`,s3robe:`Durchmesser`,"7puwki":`Höhe`,kbxnhn:`Gedreht`,"7nkn2r":`Position, vom Start aus`,v1hcj2:`Voraus`,"1vf2pel":`Nach rechts`,"1xakelj":`Shift`,"1esrfu8":`Schritte von 5 cm, 15°`,yvgdmk:`Alt`,"1w55ans":`Größe von der Mitte aus`,"1xzs12p":`verschieben ·`,"14bbmnu":`drehen`,g7xa5b:`Arena · 3 × 3 m`,vmlwpb:`Rückgängig`,"2zps2o":`Zurücksetzen`,ew9em3:`Abbrechen`,lewgh4:`Speichern`,"1vz8dhj":`Wie das Programm entscheidet`,m76rx7:`Wähle ein Kästchen, um seinen Code zu sehen`,"1hnif0x":`Programmablauf`,"11rknnz":`Live`,"540b06":`Auto`,"1fr6xqr":`Teile bereitlegen`,"1wu7r43":`Manuell`,ky4lc5:`Stopp`,"152av8f":`Aktoren`,"1df7dln":`Summer`,pksfl2:`fahren ·`,"1hrh82t":`Leertaste`,"9zyeew":`stopp ·`,jw8yab:`Modus ·`,j4ckle:`Summer ·`,kzo6rh:`Verfolger`,mcpijf:`Serieller Monitor`,"1aeugy":`Leeren`,"1jgmzoq":`← Zurück`,c9ljxw:`Schritte`,"1padbm0":`Weiter`,g6g542:`Zurück zum Schritt`,"1k7z1pa":`Esc`,dpexcn:`Daten`,"8f4gnm":`Zum Schritt`,qy3p54:`EINSTELLUNGEN`,"12znfuf":`Der Fahrschritt verbindet sich mit`,"17rhf7d":`Echtes Auto (ESP32 über WLAN)`,dsq8ip:`Adresse des Autos`,"1ihj7t4":`Anzeige & Ton`,oh792y:`Summer über die Lautsprecher abspielen`,"1bxmuya":`Ultraschallstrahl anzeigen`,"1gxdv01":`Kamera folgt dem Auto`,"9mmtn3":`Simulation zurücksetzen`,"1k6e5zv":`Übernehmen`,"1iptqu5":`Ungültige URL „{url}“`,"12bfr2h":`Die URL muss mit ws:// oder wss:// beginnen`,"1s22nop":`Verbinde mit {url}`,"1q17yrm":`Neuer Versuch in {s} s`,hsi0bv:`Keine Daten vom Auto`,ye8ewg:`Verbunden`,"1puhp9v":`Verbinde…`,y1y3f2:`Keine Daten`,ci4tze:`Getrennt`,"1fmx9lv":`Verbindungsfehler`,"19wtqq3":`Verbunden · {board}`,"1b4ym3j":`Eingebauter Simulator`,bgnl0z:`Grafik wird vorbereitet`,"39rjx0":`Bereit`,"1ruee97":`Die 3D-Werkbank konnte nicht starten. Sie braucht WebGL: probiere einen anderen Browser oder schalte die Hardwarebeschleunigung ein.`,xa5swu:`TESTARENA`,"18xfupg":`Fahre mit den Bedienelementen rechts`,khccvm:`Fahre mit W A S D oder den Bedienelementen rechts`,vhwww6:`Schritt {n} · {title}`,"1i98668":`Das Auto wird gebaut`,y9b5jm:`Die Teile werden ausgelegt`,qzfxj5:`Zeile {n} auf der Werkbank zeigen`,pj86x7:`Das auf der Werkbank zeigen`,"13bzcw5":`Kopiert`,"8gdme8":`Markieren & kopieren`,s6g5lw:`Kopieren`,"1bstp0v":`Stückliste`,"1g4j0cl":`Du brauchst`,"15cdqf0":`Werkzeug`,"1wrxvmg":`So geht’s`,"1x0ptmh":`Pinbelegung · {board}`,"1go9otx":`Sketche`,zvnhd5:`Sketch`,t8quxl:`Herunterladen`,na9qmv:`Wenn etwas nicht stimmt`,"5mau71":`Hinweis`,"1xh5jos":`{kicker} · Schritt {n} von {total}`,slbawy:`Weiter: {step} →`,"7rhhil":`Von vorn ↺`,"1mtyvb1":`Schritt {n}: {step} · {done} / {total} abgehakt`,"4x1xaj":`Schritt {n}: {step}`,d2gue0:`Pappkarton`,"1xebpbq":`Holzklotz`,hi63vm:`Blechdose`,"14yz9o9":`Blumentopf`,"1g6nbya":`Es muss innerhalb der Wände bleiben.`,v23nvk:`Der Startplatz des Autos muss frei bleiben.`,"1d1sqge":`Dort steht das Auto.`,sjcnug:`Zwei Hindernisse können nicht am selben Ort sein.`,"1rjq9tt":`Ziehe ein Hindernis, um es zu verschieben. Die eckigen Griffe ändern seine Größe, der runde dreht es.`,qaws2z:`Die Arena von oben. Klicke auf ein Hindernis, um es auszuwählen, und ziehe es, um es zu verschieben. Mit der Tastatur: Bild ab und Bild auf wählen ein Hindernis, die Pfeiltasten verschieben es, R dreht es.`,km6rtw:`Hindernis`,v6zgjh:`Die Arena im Originalzustand. Beim Speichern kommt das Auto zurück an den Start.`,"1bneya5":`Jede Runde beginnt hier`,"1gvmqkj":`Entscheidung`,"2wk0tb":`Aktion`,ltbyq8:`ja`,r90oai:`nein`,"10pfeta":`{file} · Zeilen {lines}`,"1mv69ab":`{file} · Zeile {lines}`,v5glvz:`kein Echo`,"1y6bn7c":`links {left} · rechts {right}`,"17yvayv":`Weg frei: weiterfahren`,g8loky:`{reading} voraus · hält unter {stop} cm`,"1qpxp29":`Stopp · LED an · Piepton`,lman68:`Hindernis bei {reading} · unter {stop} cm`,"4e4gg4":`Zurückgesetzt: umschauen`,"1x1kke3":`der Messwert hatte sich {s} s lang nicht geändert`,"1pc4lzp":`Zurückgefahren: erneut schauen`,"11qad25":`beide Seiten waren zu eng zum Drehen`,dfsfd7:`Festgefahren: zurücksetzen`,eic5lt:`Messwert {s} s lang unverändert`,n7w5mt:`Kein Platz zum Drehen: zurückfahren`,etina8:`{sides} · unter {tight} cm`,crgp5w:`Schaut nach rechts`,vto9jk:`misst {reading}`,"1xubspn":`Schaut nach links`,"92dcjq":`rechts {right} · links misst {reading}`,cfs13v:`Platz zum Drehen?`,h7zzeh:`{sides} · braucht {tight} cm`,qlw2zr:`Dreht wieder nach links`,"1fd6gkc":`Dreht wieder nach rechts`,"1hj21ci":`direkt nach einer Drehung blockiert: gleiche Richtung`,"1jk1kpr":`Dreht nach links`,u6ps9c:`Dreht nach rechts`,"1uvg70v":`Auto ist aus`,"1bbdvwo":`Live-Ansicht: nur simuliertes Auto`,"1fj8dwo":`schalte auf Auto, um dem Auto beim Entscheiden zuzusehen`,"14g7i3l":`ein echtes Auto meldet Messwerte, nicht den Schritt seiner Routine`,"15nlm70":`Zurück zu Schritt {n} · {step}`,"1i8tm8j":`Eingebaut in <b>diesem Schritt</b>`,rpu2qi:`Eingebaut in <b>Schritt {n} · {step}</b>`,"1b4o3fw":`Zu Schritt {n} →`,y322vs:`Sprache: {name}`,bk85tv:`Abspielen`,"1x4eyna":`{action} (Leertaste)`,gpdo6z:`Verwende eine Adresse mit ws:// oder wss://, z. B. ws://192.168.4.1:81/`,"1iquufv":`Verbinde dich zuerst mit dem WLAN des Autos. In README.md steht das Nachrichtenformat, das die Firmware sprechen muss.`,njqkz2:`Gib eine WebSocket-URL ein, z. B. ws://192.168.4.1:81/`,nrzvmi:`Fährt ein simuliertes Auto durch eine Testarena — keine Hardware nötig.`,cegybp:`Teile`,wv4sck:`Vorbereitung`,"7z3mbb":`Alles für einen vierrädrigen Rover mit einem Ultraschall-„Kopf“, der sich umschauen kann. Lege die Teile so aus und hake jedes einzeln ab. Fahre mit der Maus über eine Zeile, um das Teil auf der Matte zu finden, oder klicke auf ein Teil für Details.`,"1x97es5":`Lade die 18650-Zellen vor dem Start in einem richtigen Li-Ion-Ladegerät und verwende geschützte Zellen: eine ungeschützte Zelle kann bei einem Kurzschluss Dutzende Ampere liefern.`,"13wu8qd":`Acryl-Chassis — untere, mittlere und obere Platte`,"9z9vwl":`TT-Getriebemotoren (3–6 V, 1:48) mit 8 T-förmigen Acryl-Haltern, 8 M3 × 30-Bolzen und Muttern`,"1qr4ely":`Räder, 65 mm`,cmzolq:`L9110S-Doppelmotortreiber-Modul`,"1qgfn27":`Arduino UNO R3 + Sensor Shield V5 + USB-Kabel`,"15cdntm":`ESP32 DevKit V1 (30 Pins) + Erweiterungsboard + USB-Kabel`,mfnvxi:`HC-SR04-Ultraschallsensor + sein Servohalter und Schrauben`,"15iavp3":`SG90-Mikroservo mit Servohörnern und Schrauben`,"1allzrf":`18650-Li-Ion-Zellen (geschützt) + Halter für 2 Zellen in Reihe mit Anschlusskabeln`,xooybo:`Schiebeschalter, 10-mm-LED rot, 220-Ω-Widerstand, aktiver 5-V-Summer`,"1csc29i":`Schiebeschalter, 10-mm-LED rot, aktiver 5-V-Summer, NPN-Transistor (PN2222A oder S8050), Widerstände 220 Ω, 2 × 1 kΩ und 2 kΩ`,"17dpcif":`DC-Hohlstecker mit Schraubklemmen, 5.5 × 2.1 mm`,bozwcy:`20 Jumperkabel Buchse–Buchse, 15 cm; roter und schwarzer Schaltdraht; 16 M3-Messing-Abstandsbolzen Innen–Innen (8 × 25 mm, 4 × 15 mm, 4 × 10 mm), 32 Schrauben M3 × 6 mm, Schaumstoff-Klebeband, Schrumpfschlauch`,"5z6ae7":`Lötkolben, Lötzinn`,"1xhh6dp":`Motorkabel, der Schalter, LED- und Summerkabel`,"11dguvz":`Kleine Schraubendreher`,"1b1pnob":`Kreuzschlitz für die M3-Schrauben, Schlitz für die Klemmen von Treiber und Stecker`,"1ligzav":`Seitenschneider / Abisolierzange`,"3pb5yx":`Schaltdraht und Jumperkabel schneiden und abisolieren`,"1avt53n":`Multimeter`,"1slxnnr":`die Polarität prüfen, bevor Strom fließt`,"100w2b7":`Li-Ion-Ladegerät`,"64j96q":`für die 18650-Zellen`,"1heknmc":`Computer, Arduino IDE`,"1mo2nzj":`um den Code in Schritt 9 hochzuladen`,t9gk37:`Motoren`,"15i6udf":`Bauen`,"1fofbt3":`Motoren & Räder`,"15llile":`Jeder TT-Motor ist ein kleiner DC-Motor, der ein Kunststoffgetriebe 1:48 antreibt. Die zwei linken und die zwei rechten Motoren drehen immer gemeinsam, wie die Ketten eines Panzers: das Auto lenkt, indem die beiden Seiten unterschiedlich schnell laufen.`,k5fimq:`Rot an der inneren Lasche jedes Motors ist das, was dich in Schritt 4 Rot mit Rot verbinden lässt: der vordere und der hintere Motor einer Seite schauen einander an, also haben ihre inneren Laschen dieselbe Aufgabe. Die Laschen sind dünn und brechen ab, wenn an einem Kabel gezogen wird, also klebe jedes Kabelpaar an seinem Motor fest. Die Kabel stehen in der Mitte, damit der lange Schlitz der mittleren Platte in Schritt 3 über sie herabkommen kann.`,"7fte4n":`Untere Platte`,rbcm1a:`TT-Getriebemotoren`,sjfn38:`T-förmige Acryl-Motorhalter`,"732lu":`M3 × 30-Bolzen und Muttern`,skq14t:`Räder`,"1s4rmq":`Stelle die vier Motoren an ihren Platz auf der unteren Platte, Wellen nach außen und Motorenden zur Mitte. Löte an jeden zwei etwa 15 cm lange Kabel: Rot an die Lasche näher zur Mitte des Autos, Schwarz an die Lasche näher zum Rad. Stelle die acht Kabel gemeinsam in der Mitte der Platte auf.`,"1mrwedd":`Nimm die Platte hoch. Schiebe von unten einen Halter durch den Schlitz an der Innenseite jedes Motors und einen weiteren in die Kerbe am Rand der Platte außen daneben. Stecke zwei M3 × 30-Bolzen durch Halter, Getriebe und Halter, Köpfe auf der Radseite, und ziehe auf jedem eine Mutter fest.`,"13sq8kw":`Stecke ein Rad auf jede Welle. Die Welle hat zwei Abflachungen, die in die Nabe greifen, sodass das Rad nicht durchrutschen kann.`,"199dyzl":`Platten`,qr73r6:`Platten stapeln`,kig8cy:`Messing-Abstandsbolzen heben die mittlere Platte 25 mm über die untere, über die 22 mm hohen Motorgetriebe hinweg, und geben der Elektronik einen ebenen Boden. Jeder Abstandsbolzen hat an beiden Enden ein Gewinde: eine Schraube kommt von unten durch die Platte darunter, eine andere geht von oben durch das, was darauf sitzt.`,"1w8a39y":`Acryl reißt, wenn du es zu fest anziehst, also reicht handfest. Chassis unterscheiden sich: hat deins kein Loch dort, wo der Controller eins braucht, halten zwei Abstandsbolzen und ein Schaumstoffpad unter dem anderen Ende ein Board fest.`,jcqip:`Mittlere Platte`,u6l9bq:`M3 × 25 mm Messing-Abstandsbolzen`,"4cdagt":`M3 × 10 mm Messing-Abstandsbolzen (für den Controller)`,xaqs1y:`M3 × 15 mm Messing-Abstandsbolzen (für die obere Platte)`,"300byl":`Schrauben M3 × 6 mm`,tezznv:`Schraube acht 25-mm-Abstandsbolzen an die untere Platte, vier an jeder Seite, jeden auf eine von unten eingesetzte Schraube.`,"70hnlv":`Bevor die mittlere Platte draufkommt, solange du noch darunter kommst, befestige die vier 10-mm-Abstandsbolzen unter den Montagelöchern des Controllers (halte das Board in Position, um zu sehen, welche Löcher der Platte passen) und die vier 15-mm-Abstandsbolzen an den Ecken ihrer hinteren Hälfte, jeden mit einer Schraube von unten.`,"1tynoxv":`Senke die mittlere Platte auf die 25-mm-Abstandsbolzen ab, fädle dabei die Motorkabel durch den langen Schlitz in ihrer Mitte nach oben und schraube sie fest.`,"1n5adbz":`Treiber`,"1ri406w":`Motortreiber einbauen`,"5n5nar":`Ein Mikrocontroller-Pin sollte nicht mehr als etwa 20 mA liefern, aber ein TT-Motor zieht beim Fahren einige hundert mA und blockiert über 1 A. Das L9110S-Modul hat zwei H-Brücken, die den Batteriestrom durch die Motoren schalten und umkehren können.`,"1uicxnj":`Welche Schraube einer Klemme welches Paar bekommt, ist noch egal: der Verdrahtungstest in Schritt 9 zeigt, ob eine Seite rückwärts läuft oder ein Rad gegen seinen Partner dreht. Lass die 6-polige Stiftleiste (B-IA, B-IB, GND, VCC, A-IA, A-IB) frei: der Strom kommt in Schritt 7, die Signale in Schritt 8. Der L9110S verträgt 800 mA pro Kanal, und jeder Kanal treibt hier zwei Motoren: gut für normales Fahren, aber halte die Räder nicht blockiert. Werden die Chips heiß, ist ein TB6612FNG-Modul (1.2 A pro Kanal) ein robusterer Ersatz.`,utkklb:`Pad aus doppelseitigem Schaumstoff-Klebeband`,syij08:`Klebe den Treiber mit Schaumstoff-Klebeband auf die mittlere Platte, vor die Abstandsbolzen des Controllers und links von der Mitte: die 6-polige Stiftleiste zur linken Kante des Autos, die Schraubklemmen zur Mitte des Autos.`,"15kkcap":`Biege die Kabel um, nach vorn entlang der Platte und herum in die Klemmen des Treibers. Verdrille die beiden roten Kabel der linken Motoren miteinander und ihre beiden schwarzen miteinander, und schraube die zwei Paare in MOTOR-A, die Klemme näher am Controller. Mach dasselbe mit den Kabeln der rechten Motoren in MOTOR-B.`,"18rvg69":`Controller`,ync8b9:`Arduino UNO montieren`,"1u68uls":`ESP32 montieren`,ertyxs:`Der Arduino UNO (ATmega328P, 16 MHz, 5-V-Logik) führt deinen Sketch aus. Ein Sensor Shield V5 wird obendrauf gesteckt und gibt jedem Pin eine eigene G / V / S-Stiftleiste (Masse, 5 V und Signal), denn die Stromleiste des UNO hat nur einen 5-V-Pin, den sich Servo und Sensor teilen müssten.`,"1p7bu2t":`Der ESP32 (Dual-Core, bis 240 MHz, WLAN und Bluetooth, 3.3-V-Logik) führt deinen Sketch aus und lässt RoboKit das echte Auto über WLAN fahren. Sein Erweiterungsboard ergänzt eine DC-Buchse mit Spannungsregler und eine G / V / S-Stiftleiste für jeden Pin.`,ii2aq7:`Die Pins des UNO arbeiten mit 5 V, also werden Sensor und Servo direkt am Shield angeschlossen.`,"1ghuj2z":`ESP32-Pins arbeiten mit 3.3 V und vertragen keine 5 V, deshalb bekommt der Echo-Ausgang des Sensors in Schritt 8 einen Spannungsteiler.`,t5ws5g:`ESP32 DevKit V1 (30 Pins)`,"1tu8qz5":`ESP32-Erweiterungsboard (30 Pins)`,"14w4gx0":`Schraube den UNO auf die vier 10-mm-Abstandsbolzen hinter dem Treiber, mit USB- und DC-Buchse zur linken Seite des Autos.`,hw767j:`Drücke das Sensor Shield V5 auf den UNO, jeden Pin in seine Buchse. Lass den SEL-Jumper gesteckt, damit die V-Pins des Shields 5 V vom UNO bekommen, und schließe nichts an die Schraubklemme des Shields an.`,"1opbgrl":`Schraube das Erweiterungsboard auf die vier 10-mm-Abstandsbolzen hinter dem Treiber, mit der DC-Buchse zur linken Seite des Autos.`,"1xxnsy2":`Setze das DevKit so in die beiden Buchsenleisten, dass jeder Pinname darauf zum Namen neben der Buchse passt. Ein um einen Pin verschobenes Board legt Strom auf die falschen Pins.`,ua2sfx:`Stelle den Jumper der V-Pins auf 5 V, denn Servo, HC-SR04 und Summer brauchen 5 V. Erweiterungsboards unterscheiden sich, also prüfe die Beschriftung des Jumpers auf deinem.`,"1jzloyj":`Sensor`,"19ot7f3":`Sensorkopf`,jii9ss:`Der HC-SR04 sendet einen Ultraschallimpuls mit 40 kHz und misst die Zeit bis zum Echo: Abstand in cm ≈ Echozeit in µs ÷ 58. Er misst von 2 cm bis etwa 4 m in einem etwa 15° breiten Strahl. Auf einem SG90-Servo montiert, kann er nach links und rechts schauen, bevor das Auto dreht.`,"1s5nsw8":`Um den Servo zu zentrieren, stecke ihn an die A5-Leiste des Shields (Braun auf G) und lade einen der beiden Sketche aus Schritt 9 hoch: beide lassen den Kopf auf 90°. Die Abtriebswelle mit Gewalt zu drehen, kann die Kunststoffzahnräder zerstören. So herum montiert, liegen die Pins des Sensors von vorn gesehen von links: GND, Echo, Trig, VCC.`,"3b6msg":`Um den Servo zu zentrieren, stecke ihn an die GPIO 23-Leiste (Braun auf G, V auf 5 V) und lade die Firmware aus Schritt 9 hoch, deren setup() servoWrite(90) aufruft. Die Abtriebswelle mit Gewalt zu drehen, kann die Kunststoffzahnräder zerstören. So herum montiert, liegen die Pins des Sensors von vorn gesehen von links: GND, Echo, Trig, VCC.`,"2934zx":`SG90-Mikroservo, einarmiges Servohorn und Schrauben`,"1o4q0ha":`Servohalter für den HC-SR04, mit seinen Schrauben`,"87cfw2":`HC-SR04-Ultraschallsensor`,"1bhe6w2":`Halte den Servo über den rechteckigen Ausschnitt vorn in der mittleren Platte, Abtriebswelle oben und auf der Mittellinie des Autos. Führe seinen Stecker durch den Ausschnitt nach unten, unter der Platte nach hinten und durch den kleinen Schlitz dahinter wieder nach oben, und zieh das Kabel durch, bis der Stecker neben dem Controller auf der Platte liegt. Dann senke den Servo in den Ausschnitt, das Kabel läuft durch die Kerbe an seinem Ende nach unten, schiebe das überschüssige Kabel unter die Platte, weg von der Motorwelle, und schraube die beiden Laschen des Servos an die Platte.`,"7x26fs":`Zentriere den Servo, drücke dann ein einarmiges Servohorn nach vorn zeigend auf seine Welle und befestige es mit der Hornschraube.`,"3f8bcm":`Schraube den Halter an das Horn, aufrecht nach vorn.`,"178kb38":`Schraube den HC-SR04 vorn an den Halter, durch die beiden Ecklöcher einer langen Kante, diese Kante unten und die Pins oben: so gehen seine Kabel nach oben weg, frei vom Servo.`,"1jamndy":`Strom`,tboesy:`Zwei 18650-Zellen in Reihe liefern nominal 7.4 V (8.4 V voll, etwa 6 V leer). Der Schalter unterbricht das +-Kabel der Batterie. Alles trifft sich an einem DC-Hohlstecker mit Schraubklemmen: die beiden Batteriekabel gehen hinein, der Stecker versorgt den UNO über dessen DC-Buchse, deren Regler die 5 V für die Logik erzeugt, und zwei weitere Kabel an denselben Klemmen versorgen den Motortreiber. Der Treiber kann seinen Strom nicht von den 5-V-Pins des Shields nehmen: die kommen vom kleinen Regler des UNO, den vier Motoren überlasten würden. Teile, an die Kabel gelötet werden müssen, bekommen sie an der Werkbank, bevor sie aufs Auto kommen: schiebe zuerst ein Stück Schrumpfschlauch auf das Kabel und schrumpfe es danach über die Lötstelle.`,r69l9i:`Zwei 18650-Zellen in Reihe liefern nominal 7.4 V (8.4 V voll, etwa 6 V leer). Der Schalter unterbricht das +-Kabel der Batterie. Alles trifft sich an einem DC-Hohlstecker mit Schraubklemmen: die beiden Batteriekabel gehen hinein, der Stecker versorgt das Erweiterungsboard über dessen DC-Buchse, deren Regler die 5 V und 3.3 V für die Logik erzeugen, und zwei weitere Kabel an denselben Klemmen versorgen den Motortreiber. Der Treiber kann seinen Strom nicht von den 5-V-Pins des Boards nehmen: die kommen von seinem kleinen Regler, den vier Motoren überlasten würden. Teile, an die Kabel gelötet werden müssen, bekommen sie an der Werkbank, bevor sie aufs Auto kommen: schiebe zuerst ein Stück Schrumpfschlauch auf das Kabel und schrumpfe es danach über die Lötstelle.`,"175zcey":`Prüfe die Polarität zweimal, bevor du die Zellen einsetzt: die Buchse des UNO hat Plus in der Mitte, und die +-Klemme des Steckers ist sein Mittelpin (prüfe mit einem Multimeter). Lade nach, wenn der Akku auf etwa 7 V fällt, darunter kann der Regler des UNO keine 5 V halten. Leuchtet keine LED, schalte sofort aus und prüfe die Verdrahtung, bevor du es erneut versuchst. LED und Summer bleiben bis Schritt 8 auf der Werkbank.`,t60ux3:`Prüfe die Polarität zweimal, bevor du die Zellen einsetzt: die meisten Erweiterungsboards haben Plus in der Mitte, aber prüfe das Symbol neben der Buchse, und die +-Klemme des Steckers ist sein Mittelpin (prüfe mit einem Multimeter). Lade nach, wenn der Akku auf etwa 7 V fällt. Leuchtet keine LED, schalte sofort aus und prüfe die Verdrahtung, bevor du es erneut versuchst. LED und Summer bleiben bis Schritt 8 auf der Werkbank.`,mvli44:`Obere Platte + 4 Schrauben M3 × 6 mm`,"1dowjmo":`2 × 18650-Halter mit Kabeln, 2 Zellen`,"83x4u2":`Schiebeschalter`,"1in9b4e":`DC-Hohlstecker mit Schraubklemmen (Mitte +)`,l8wrh1:`10-mm-LED rot + 220-Ω-Widerstand`,"24gtky":`Aktiver 5-V-Summer`,"14zuroc":`Aktiver 5-V-Summer, NPN-Transistor + 1-kΩ-Widerstand`,"1pgj6ai":`Schaumstoff-Klebeband, Schrumpfschlauch, 4 Jumperkabel zum Zuschneiden: 2 rote, 2 schwarze`,"1ewjpxi":`Schaumstoff-Klebeband, Schrumpfschlauch, 5 Jumperkabel zum Zuschneiden: 2 rote, 2 schwarze, 1 orangefarbenes`,y2bs3a:`Lege die obere Platte auf die vier 15-mm-Abstandsbolzen und schraube sie fest.`,anc24f:`Schneide an der Werkbank das rote Kabel des Batteriehalters etwa 2 cm vom Halter ab. Löte das Ende am Halter an einen äußeren Pin des Schalters und 10 cm des abgeschnittenen Stücks an den mittleren Pin.`,"1mixan6":`Halte den Halter über die obere Platte, seine Kabel zur linken Seite des Autos. Führe das schwarze Kabel durch das Loch an der linken Kante der Platte nach unten und zieh es nach vorn entlang der mittleren Platte, während du den Halter absenkst. Klebe den Halter mit zwei Streifen Schaumstoff-Klebeband fest, und den Schalter seitlich an die linke Kante der Platte, Hebel nach außen. Dann lege das rote Kabel nach vorn, über die vordere Ecke der Platte hinaus. Beide Kabel sollten neben der DC-Buchse des Controllers enden.`,"1xim7b6":`Schneide ein rotes und ein schwarzes Jumperkabel 12.5 cm von einem Ende ab. Stecke die Buchse des langen roten Stücks auf den VCC-Pin des Treibers und die des langen schwarzen auf GND, und lege beide entlang der linken Kante der mittleren Platte zurück zur Buchse.`,"1200i":`Schneide ein rotes und ein schwarzes Jumperkabel 11 cm von einem Ende ab. Stecke die Buchse des langen roten Stücks auf den VCC-Pin des Treibers und die des langen schwarzen auf GND, und lege beide entlang der linken Kante der mittleren Platte zurück zur Buchse.`,"1nymzxl":`Isoliere die vier losen Enden 5 mm ab. Schraube beide roten unter die +-Schraube des Steckers und beide schwarzen unter −, dann stecke den Stecker in die DC-Buchse des UNO, so gedreht, dass + oben ist.`,f3jc5e:`Isoliere die vier losen Enden 5 mm ab. Schraube beide roten unter die +-Schraube des Steckers und beide schwarzen unter −, dann stecke den Stecker in die DC-Buchse des Erweiterungsboards, so gedreht, dass + oben ist.`,hhvzfi:`Löte an der Werkbank den 220-Ω-Widerstand in Reihe an das lange (+) Bein der LED. Schneide ein rotes und ein schwarzes Jumperkabel in der Mitte durch. Löte eine rote Hälfte an das freie Ende des Widerstands und eine schwarze Hälfte an das kurze Bein der LED.`,"1qz1083":`Biege die beiden Pins des Summers flach. Löte die andere rote Hälfte an + (der längere Pin, oben markiert) und die andere schwarze Hälfte an −.`,"110bbxt":`Biege die beiden Pins des Summers flach und löte die andere rote Hälfte an + (der längere Pin, oben markiert). Löte den Kollektor des Transistors an den −-Pin und einen 1-kΩ-Widerstand an seine Basis, dann ein halbes orangefarbenes Jumperkabel an den Widerstand und die andere schwarze Hälfte an den Emitter. Schrumpfe einen Schlauch über Transistor und Widerstand. Prüfe im Datenblatt deines Transistors, welches Bein welches ist.`,"1avlub7":`Prüfe, dass keine blanke Lötstelle eine andere berühren kann und dass der Schalter aus ist. Dann setze die beiden Zellen in den Halter, jedes +-Ende dort, wo der Halter + zeigt. Schalte kurz ein: die Betriebs-LEDs am Controller und am Treiber sollten beide leuchten.`,k2hc2b:`Verdrahtung`,s234wa:`Verkabeln`,"1po8toc":`Jeder Sensor und Aktor steckt an einer G / V / S-Stiftleiste des Shields, also teilen alle die Masse des UNO; die Masse des Treibers kommt von der Batterie, über die DC-Buchse dieselbe Masse. Die Pins sind danach gewählt, wo jedes Teil sitzt, sodass die Kabel sich von den Leisten auffächern, ohne sich zu kreuzen. Arbeite in dieser Reihenfolge, Schalter aus: zuerst die LED, tief unten am linken Ende der Leiste, und zuletzt die vier Kabel des Sensors, weil sie sich über alles andere wölben. Ein Jumperkabel kommt Ende für Ende dran: eine Buchse ganz auf ihren Pin drücken, das Kabel umbiegen, die andere aufstecken. Fahre mit der Maus über eine Zeile, um das Kabel am Modell zu sehen.`,"1ylwoyd":`Jeder Sensor und Aktor steckt an einer G / V / S-Stiftleiste des Erweiterungsboards, also teilen alle die Masse des ESP32; die Masse des Treibers kommt von der Batterie, über die DC-Buchse dieselbe Masse. Die Pins sind danach gewählt, wo jedes Teil sitzt, sodass die Kabel sich von den Leisten auffächern, ohne sich zu kreuzen. Arbeite in dieser Reihenfolge, Schalter aus: zuerst die LED, tief unten am linken Ende der Leiste, und zuletzt die Kabel des Sensors, weil sie sich über alles andere wölben. Ein Jumperkabel kommt Ende für Ende dran: eine Buchse ganz auf ihren Pin drücken, das Kabel umbiegen, die andere aufstecken. Fahre mit der Maus über eine Zeile, um das Kabel am Modell zu sehen.`,"10tvb2g":`D5 und D11 tragen das Tempo jeder Seite: es sind PWM-Pins, die weiter funktionieren, während die Servo-Bibliothek läuft (sie belegt Timer1, was PWM auf D9 und D10 abschaltet). D6 und D12 tragen die Richtung. Servo und Summer nutzen A5 und A0 als gewöhnliche Digitalpins. Alle G-Pins sind verbunden, ebenso alle V-Pins: GND und VCC des Sensors können auf die jeweils nächstgelegenen.`,it0an4:`Der 1 kΩ / 2 kΩ-Teiler macht aus dem 5-V-Echo-Impuls 3.3 V (5 V × 2 ⁄ 3). Echo nutzt GPIO 35, einen der reinen Eingangspins (34–39): Lesen ist alles, was er tun muss. Der Summer läuft vom 5-V-V-Pin und der Transistor schaltet ihn, denn 3.3 V liegen unter dem, was ein 5-V-Summer braucht. Die Ausgänge meiden GPIO 0, 2, 5, 12, 14 und 15, die Strapping-Pins sind oder beim Booten des ESP32 pulsen. Alle G-Pins sind verbunden, ebenso alle V-Pins.`,"16ffufp":`LED: neben die vordere linke Ecke des Controllers kleben · rot → S · schwarz → G`,"55vkwv":`Treiber A-IA / A-IB (links)`,"1wr2rcy":`Treiber B-IA / B-IB (rechts)`,"12y58k1":`Servokabel (braun G, rot V, orange S)`,"1xjcvwz":`Summer: vorn auf die obere Platte kleben · rot → S · schwarz → G`,"1h6hx3u":`HC-SR04 Trig → S · VCC → V · GND → G von D2`,zvbj2f:`HC-SR04 Echo`,"83uabx":`Summer: vorn auf die obere Platte kleben · rot → V · orange (Basis) → S · schwarz (Emitter) → G`,"1eb7xia":`HC-SR04 Trig → S · VCC → V · GND → G von GPIO 34`,"1ig2p4r":`HC-SR04 Echo: sein Jumperkabel 4.5 cm von einem Ende durchschneiden · 1 kΩ zwischen die Stücke · 2 kΩ weiter zu 4.7 cm, abgeschnitten vom Ende eines schwarzen Jumperkabels · kurze Stücke → S und G`,xoaiok:`Code`,"1if8prf":`Programmieren`,"1g03ums":`Code hochladen`,"1bv2ey7":`Zwei Sketche. Der Verdrahtungstest geht jedes Teil der Reihe nach durch, sodass du siehst, dass jedes angeschlossen ist und beide Seiten richtig herum drehen. Der Hindernisvermeider ist das Programm des Autos: es fährt, bis etwas näher als 22 cm ist, schaut mit dem Kopf nach rechts und links und dreht zur Seite mit mehr Platz.`,"8lzj5q":`Diese Firmware macht den ESP32 zu einem WLAN-Access-Point. Sie führt die Befehle aus, die RoboKit sendet (Fahren, Tempo, Modus, Servo, LED und Summer), hält an, wenn keine mehr ankommen, und schickt 10-mal pro Sekunde den Abstand und den Motorzustand zurück. Im Auto-Modus weicht sie Hindernissen selbst aus, mit derselben Routine, die der Simulator ausführt.`,saufbh:`Wenn nichts den Ping zurückwirft, hält der HC-SR04 Echo etwa 38 ms lang high (der Wert aus dem Datenblatt; manche Module länger). Das liegt über dem Timeout von 30 ms, also gibt pulseIn() 0 zurück. Der Vermeider zählt das als 400 cm, „frei“, nicht als „berührt“. Sein Strahl ist schmal, also kann das Auto an einer Ecke hängen bleiben, die es nie gesehen hat: ein Messwert, der sich nicht mehr ändert, während die Räder schieben, sagt ihm, dass es festsitzt. Und ist es direkt nach einer Drehung wieder blockiert, dreht es noch einmal in dieselbe Richtung statt zurück: in einer Ecke würde es sonst ewig links, rechts, links drehen.`,"11hew0t":`ledcAttach() und ledcWrite(pin, duty) sind die API von arduino-esp32 3.x; die älteren Aufrufe ledcSetup() und ledcAttachPin() aus 2.x kompilieren nicht mehr. Der Strahl des Sensors ist schmal, also kann das Auto in Auto an einer Ecke hängen bleiben, die es nie gesehen hat: ein Messwert, der sich nicht mehr ändert, während die Räder schieben, sagt ihm, dass es festsitzt. Und ist es direkt nach einer Drehung wieder blockiert, dreht es noch einmal in dieselbe Richtung statt zurück: in einer Ecke würde es sonst ewig links, rechts, links drehen.`,"3zk06m":`Wähle in der Arduino IDE Tools → Board → Arduino UNO und den richtigen Port. Beide Sketche nutzen die Servo-Bibliothek, die mit der IDE kommt.`,j0z2nr:`Bock das Auto auf, sodass alle vier Räder den Tisch nicht berühren. Lade den Verdrahtungstest hoch, schalte die Batterie ein und öffne den Serial Monitor mit 115200 Baud. Sieh zu, wie jede nummerierte Zeile passiert: LED und Piepton, Kopf rechts, links und Mitte, dann jede Seite vorwärts und rückwärts.`,"1dz2oap":`Korrigiere, was nicht gestimmt hat (siehe die Liste unten). Dann lade den Hindernisvermeider hoch, zieh das USB-Kabel ab, stell das Auto auf den Boden und schalte ein: es wartet zwei Sekunden und fährt dann los.`,"4czqhs":`Ändere TURN_MS im Sketch, bis jede Drehung auf deinem Boden etwa eine Vierteldrehung ist.`,rgjhux:`Füge in der Arduino IDE https://espressif.github.io/arduino-esp32/package_esp32_index.json unter File → Preferences → Additional boards manager URLs hinzu. Installiere dann „esp32 by Espressif Systems“ Version 3.x aus dem Boards Manager und wähle ESP32 Dev Module.`,"118rr9r":`Installiere aus dem Library Manager das neueste „WebSockets“ von Markus Sattler und „ArduinoJson“ Version 7 von Benoit Blanchon.`,nbb8bl:`Lade hoch, bock dann das Auto auf, sodass alle vier Räder den Tisch nicht berühren, und schalte die Batterie ein. Verbinde dich mit dem WLAN „RoboKit“ (Passwort drive1234), geh zu Schritt 10 und verbinde dich über Einstellungen → Echtes Auto (ESP32 über WLAN).`,srtywe:`Probiere jedes Bedienelement der Reihe nach: LED, Summer, den Servo-Schieberegler, dann W A S D. Dreht eine Seite falsch herum, siehe die Liste unten. Dann stell das Auto auf den Boden, probiere Auto und ändere TURN_MS, bis jede Drehung etwa eine Vierteldrehung ist.`,sp50jr:`Beim Einschalten leuchtet nichts`,"1gg4m0p":`Schalte aus. Prüfe, ob die Zellen geladen und richtig herum eingelegt sind, ob die roten Kabel unter der +-Schraube des Steckers sitzen und ob der Schalter zwischen seinem mittleren Pin und einem äußeren Pin verdrahtet ist.`,"9crnd5":`Eine Seite dreht im Test rückwärts`,"1mf4jfi":`Tausche die beiden Kabel dieser Seite in ihrer Schraubklemme: MOTOR-A ist die linke Seite, MOTOR-B die rechte.`,"1gcvytv":`Ein Rad dreht gegen seinen Partner`,"76bppn":`Tausche die beiden Kabel dieses einen Motors dort, wo sie mit denen des anderen Motors verdrillt sind.`,kakgt9:`Zeile 3 dreht die rechten Räder`,"95tfvz":`Die beiden Paare Jumperkabel sind vertauscht: A-IA / A-IB gehören an D11 / D12, B-IA / B-IB an D5 / D6.`,"1yvpqg9":`Der Kopf schaut zuerst nach links`,"3fc0ov":`Manche Servos drehen andersherum: tausche 20 und 160 in den Sketchen.`,"1ymivbo":`Der Abstand ist immer 0.0 cm`,"1wzcqly":`Es kommt kein Echo zurück. Prüfe, ob Trig an D4 und Echo an D3 ist und ob VCC und GND des Sensors auf einem V- und einem G-Pin stecken. Er zeigt auch 0, wenn innerhalb von etwa 4 m nichts ist.`,lg1f33:`Der UNO startet neu, wenn die Motoren anlaufen`,gp3cr0:`Die Batteriespannung bricht ein: lade die Zellen. Ein Kondensator mit 470–1000 µF zwischen V und G auf dem Shield (Polarität beachten) hilft der 5-V-Versorgung über die Einbrüche.`,"13n04wo":`Das Auto brummt, dreht sich aber nicht auf der Stelle`,y7q52i:`Beim Drehen schieben alle vier Reifen seitlich und es braucht mehr Kraft als geradeaus: erhöhe SPIN in Richtung MAX_PWM und lade die Zellen.`,hvphiw:`Es zieht zu einer Seite`,ittf4s:`Keine zwei Motoren sind ganz gleich. Bremse die schnellere Seite: für ein Auto, das nach rechts zieht, drive(CRUISE - 10, CRUISE).`,"19do8xl":`Das Hochladen bleibt bei „Connecting…“ stehen`,hn5crr:`Halte die BOOT-Taste des DevKit gedrückt, bis das Hochladen beginnt, und prüfe, ob das USB-Kabel Daten überträgt und nicht nur Strom.`,"144ggw6":`RoboKit verbindet sich nicht`,"1wm6oj5":`Eine Seite dreht rückwärts`,"1buhj6h":`Links und rechts sind vertauscht`,"1s6olzj":`Die beiden Paare Jumperkabel sind vertauscht: A-IA / A-IB gehören an GPIO 26 / 27, B-IA / B-IB an GPIO 33 / 25.`,svln7p:`In Auto schaut der Kopf zuerst nach links`,"1ki0m9i":`Manche Servos drehen andersherum: tausche 20 und 160 in autoStep().`,"6xg3a":`Der Abstand ist immer 400 cm`,"7himiv":`Es kommt kein Echo zurück. Prüfe, ob Trig an GPIO 32 ist, ob Echo über den Teiler GPIO 35 erreicht und ob VCC des Sensors auf einem 5-V-Pin steckt. Er zeigt auch 400, wenn innerhalb von etwa 4 m nichts ist.`,ksb87p:`Der Summer bleibt stumm`,"9czfii":`Prüfe die Beine des Transistors anhand seines Datenblatts (die Reihenfolge unterscheidet sich je nach Typ) und ob das + des Summers auf einem 5-V-Pin steckt.`,igpqu0:`Der ESP32 startet neu, wenn die Motoren anlaufen`,owaty5:`Die Batteriespannung bricht ein: lade die Zellen. Ein Kondensator mit 470–1000 µF zwischen einem 5-V-Pin und G (Polarität beachten) hilft der Versorgung über die Einbrüche.`,"1u5gnnb":`Beim Drehen schieben alle vier Reifen seitlich und es braucht mehr Kraft als geradeaus: erhöhe das Tempo und lade die Zellen.`,uak3xr:`1 · Verdrahtungstest`,"1jz093b":`2 · Hindernisvermeider`,"129dlzg":`Firmware`,ussxe7:`Simulieren`,"17ssthc":`Fahren`,bmzqy4:`Das simulierte Auto hat dieselben Teile wie deins. Fahr es durch die Testarena und schalte dann auf Auto: es führt dieselbe Routine aus wie der Sketch des Hindernisvermeiders. Es hält an einem Hindernis an und piept, schaut nach rechts und links, dreht zur Seite mit mehr Platz und setzt zurück, wenn es festsitzt.`,"189d210":`Das simulierte Auto beantwortet dieselben Befehle, die RoboKit an deinen ESP32 sendet, und Auto führt dieselbe Routine aus wie die Firmware. Wenn dein Auto gebaut ist, wechsle in Einstellungen → Echtes Auto (ESP32 über WLAN) zu ihm.`,olmdkx:`Rad, 65 mm`,psly3z:`Antrieb`,vffqvh:`Ein Gummireifen auf einer Kunststofffelge. Die Nabe hat eine Aufnahme mit zwei Abflachungen, die auf die Abtriebswelle des TT-Motors gesteckt wird, sodass das Rad nicht durchrutschen kann. Wenn das Auto auf der Stelle dreht, schieben die Reifen seitlich, also zählt die Haftung.`,jq4v4c:`Nabe`,mq93xq:`Aufnahme mit zwei Abflachungen für die Welle des TT-Motors`,"1cgpuek":`Strecke pro Umdrehung`,esl998:`≈ 20.4 cm (π × 6.5 cm)`,"11yszgp":`TT-Getriebemotor`,m5llum:`Ein kleiner DC-Motor mit Bürsten, der ein Kunststoffgetriebe 1:48 antreibt. Kehre den Strom um und das Rad dreht andersherum; senke die mittlere Spannung per PWM und es wird langsamer.`,"525amd":`Spannung`,"226us9":`Übersetzung`,jpnnsq:`≈ 200 rpm bei 6 V, ohne Last`,"1dw4k8q":`Strom`,"1p9wnb6":`≈ 150 mA ohne Last · bis ≈ 1.5 A blockiert bei 6 V`,cdauuh:`Blockiermoment`,"1gzxf67":`≈ 0.8 kg·cm bei 6 V`,ign4wl:`Gehäuse`,mad9cv:`Welle`,"14e36jb":`Ø 5.5 mm mit zwei Abflachungen im Abstand von 3.7 mm, auf beiden Seiten heraus`,feutd2:`Befestigung`,"183nrmx":`zwei Löcher Ø 3 mm im Abstand von 17.5 mm, 20 mm hinter der Welle`,"108seeu":`Motorhalter`,"1mquwkf":`Chassis`,"10qeeg1":`Ein T-förmiges Stück Acryl. Sein Steg kommt neben dem Getriebe durch die untere Platte nach oben, sein Kopf bleibt darunter, sodass er nicht durchrutschen kann. Je einer kommt an jede Seite eines Motors, und zwei lange Bolzen gehen durch beide Halter und die zwei Befestigungslöcher des Getriebes.`,"1kk17cw":`Material`,"1me4wyg":`Acryl`,st0e1p:`Pro Motor`,"8uzq1j":`2 Halter · 2 Bolzen M3 × 30 + Muttern`,"1am47c9":`Einbau`,v6cwyh:`von unter der Platte: der innere in einem Schlitz, der äußere in einer Kerbe am Rand`,"723pu9":`Trägt die vier Motoren und die acht Abstandsbolzen der mittleren Platte. Ein Schlitz und eine Kerbe am Rand neben jedem Motor nehmen die beiden Halter dieses Motors auf.`,"1n7meho":`Größe (dieses Modell)`,r4lxco:`Der Boden für die Elektronik. Durch den langen Schlitz in der Mitte kommen die Motorkabel von unten herauf, und der rechteckige Ausschnitt vorn hält den Servo; die Kerbe an seinem Ende ist für das Servokabel.`,"11vqw8c":`25 mm über der unteren Platte`,"1957t19":`Obere Platte`,"2ljc6y":`Eine halb so lange Platte hinten, die den Akku, den Schalter und den Summer über der Elektronik trägt.`,"1ytak7b":`1.5 cm über der mittleren Platte`,"1ey525v":`Messing-Abstandsbolzen, M3`,"7je4w9":`Sechskant-Abstandshalter mit Gewinde an beiden Enden. Sie halten die Platten auseinander und heben Platinen vom Acryl ab, sodass nichts an ihrer Unterseite es berührt.`,"1t2znv5":`Gewinde`,i9dhsi:`M3, Innen–Innen`,"1cazjzs":`untere → mittlere Platte (über die 22-mm-Motoren hinweg)`,rni6ay:`mittlere → obere Platte`,"1dz3bjd":`Controller-Board`,"1erre2c":`Schrauben`,"7fsd49":`eine M3 × 6 mm an jedem Ende, 32 insgesamt`,pmsrct:`Motorkabel`,h0ivdz:`Ein rotes und ein schwarzes Kabel von jedem Motor: Rot an der Lasche näher zur Mitte des Autos, Schwarz an der näher zum Rad. Die zwei Motoren jeder Seite sind parallel an einen Treiberkanal angeschlossen, Rot mit Rot und Schwarz mit Schwarz, sodass sie immer gemeinsam drehen.`,"148isqp":`jeweils etwa 15 cm`,"88dh10":`Linkes Paar`,"1hr3y9w":`MOTOR-A`,"1gp3zrj":`Rechtes Paar`,"1il2rct":`MOTOR-B`,"4iibl6":`Eine Seite läuft rückwärts?`,"1p9lbgb":`ihre beiden Paare in der Klemme tauschen`,"2380z5":`Ein Rad gegen seinen Partner?`,h5sbfv:`die beiden Kabel dieses Motors tauschen`,"19qn9l6":`L9110S-Motortreiber`,"82whm4":`Elektronik`,"12ibf8u":`Zwei L9110S-Chips mit H-Brücke, einer pro Kanal. Jeder Kanal hat zwei Eingänge: IA high und IB low dreht den Motor in eine Richtung, IA low und IB high in die andere, und beide gleich hält ihn an. PWM an einem Eingang stellt das Tempo ein.`,"25ul91":`Versorgung (VCC)`,m2phlf:`800 mA pro Kanal (1.5–2 A Spitze)`,"17s6ks8":`Eingänge`,d0m2ee:`A-IA, A-IB, B-IA, B-IB · Logik 3.3 V oder 5 V`,"4swwow":`Stiftleiste`,oja0mi:`B-IA · B-IB · GND · VCC · A-IA · A-IB (gewinkelte Pins)`,"1xbblqt":`etwa 29 × 23 mm, Befestigungslöcher Ø 3 mm (Maße variieren je nach Händler)`,"189a81e":`Ein Mikrocontroller-Board mit ATmega328P. Es führt deinen Sketch aus, liest den Sensor und entscheidet, was die Motoren tun.`,"1ebaepz":`ATmega328P @ 16 MHz`,"16qkmtv":`Logikpegel`,eslzkd:`PWM-Pins`,oopaku:`Speicher`,"8hfwsd":`32 KB Flash · 2 KB RAM`,"1jzh7y5":`Stromeingang`,"1vbs2jm":`7–12 V an der DC-Buchse (empfohlen)`,"1hxwxrt":`Strom pro Pin`,xms582:`20 mA empfohlen · 40 mA absolutes Maximum`,"1n28mf4":`Wird auf den UNO gesteckt und führt jeden Pin auf eine 3-polige G / V / S-Stiftleiste (Masse, 5 V, Signal), sodass ein Servo oder Sensor direkt mit eigener Masse und Versorgung angesteckt wird.`,e8ir2h:`Stiftleisten`,d0uaj4:`D0–D13 und A0–A5, jeweils G · V · S`,"1iy90zn":`V-Pins`,ohp32m:`5 V vom UNO, solange der SEL-Jumper gesteckt ist`,"1y4aysj":`Ohne den Jumper`,gi4ocs:`V kommt von der Schraubklemme des Shields`,"1thlwjq":`Vorsicht`,"1fzsig9":`die Schraubklemme nie versorgen, wenn SEL gesteckt ist`,"1kft85q":`Extras`,"1e4238k":`I²C- und serielle Stiftleisten`,"1jeelmn":`ESP32 DevKit + Erweiterungsboard`,"8jd2d6":`Ein Dual-Core-Mikrocontroller mit WLAN und Bluetooth, gesteckt auf ein Erweiterungsboard, das eine DC-Buchse mit Regler und eine G / V / S-Stiftleiste für jeden Pin ergänzt.`,"1inmx8d":`Modul`,qx458t:`ESP32-WROOM-32 · bis 240 MHz`,"7ra2ga":`3.3 V, nicht 5-V-tolerant`,"1chl2hi":`jeder Ausgangspin (LEDC)`,"7fk3dd":`Funk`,"1b7zmuj":`WLAN 802.11 b/g/n · Bluetooth`,pawwts:`≈ 6.5–12 V an der DC-Buchse (prüfe dein Board)`,yzyhje:`3.3 V oder 5 V, per Jumper eingestellt`,"7wntef":`SG90-Mikroservo`,mni0ct:`Ein kleiner Motor, ein Getriebe und ein Positionssensor in einem Gehäuse. Er erwartet alle 20 ms einen Impuls (50 Hz); die Impulsbreite bestimmt den Winkel: 1.5 ms ist die Mitte, und etwa 0.5–2.4 ms decken 0° bis 180° ab.`,wvoosj:`Drehmoment`,"1e13gca":`≈ 0.1 s pro 60°`,"1yo9wk7":`Größe · Gewicht`,"1oaes5p":`23 × 12 × 29 mm · 9 g`,"1b34x3l":`Kabel`,"1qalf36":`braun GND · rot V+ · orange Signal`,"1bshntj":`HC-SR04-Servohalter`,"1yr5sge":`Wird an das Servohorn geschraubt und hält den HC-SR04 an zwei seiner Ecklöcher, sodass sich der Sensor mit dem Servo dreht und sein Strahl waagerecht bleibt.`,"1t4m9bk":`Befestigung`,mnle4w:`Schrauben des Servohorns`,"1yzxd81":`Hält`,"1fp9bdu":`den HC-SR04 an zwei seiner Ecklöcher, auf Abstandshaltern`,"1yozvc2":`Andere Bauarten`,"16fhes5":`viele Halter greifen den Sensor stattdessen an seinen beiden Wandlern`,c8gdr7:`Ein 10-µs-Impuls an Trig lässt einen Wandler acht Schwingungen mit 40 kHz senden; der andere lauscht. Echo bleibt dann so lange high, wie der Schall hin und zurück gebraucht hat, also cm = µs ÷ 58 (343 m/s, halbiert).`,"198uyr6":`Reichweite`,"3xsn4q":`Strahl`,"1gw4v0v":`unter 15°`,"1oy2zwu":`Versorgung`,"1m7niep":`Ping-Rate`,"7gsn1j":`einer alle 60 ms oder langsamer`,npm5w4:`Pins (vorn, links → rechts)`,pyp646:`VCC · Trig · Echo · GND mit den Pins unten; mit den Pins nach oben montiert, wie hier: GND · Echo · Trig · VCC`,cr1wqh:`2 × 18650-Li-Ion-Akku`,"1fdnj4z":`Zwei Zellen in Reihe: 8.4 V voll, 7.4 V nominal, etwa 6 V leer. Verwende geschützte Zellen, schließe sie nie kurz und lade sie in einem richtigen Li-Ion-Ladegerät.`,w63ube:`7.4 V nominal (6–8.4 V)`,serueh:`Kapazität`,"1lup9sh":`2000–3500 mAh (echte Zellen)`,"7l22en":`Halter`,"1ka7i4l":`2 Fächer, in Reihe`,"1h1ba5m":`geschützte Zellen sind ein paar mm länger; prüfe, ob sie passen`,h4px5m:`Netzschalter`,bs7ocz:`Unterbricht das +-Kabel der Batterie, sodass das ganze Auto aus ist. Er ist zwischen seinem mittleren Pin und einem äußeren Pin verdrahtet: das rote Kabel des Halters an einem, das Kabel zum Stecker am anderen. Er liegt seitlich auf Schaumstoff-Klebeband an der linken Kante der oberen Platte, Hebel nach außen, wo ein Finger ihn erreicht.`,"1m2zofh":`Typ`,"69jc9h":`SPDT-Schiebeschalter als Ein/Aus`,w3vkqt:`Pins`,"1owufyi":`drei in einer Reihe: außen · gemeinsam · außen`,fph5dc:`Belastbarkeit`,"1bpycfc":`wähle einen für ≥ 2 A DC`,k3s7zg:`Aktiver Summer, 5 V`,"177ed2m":`Signale`,jfbt4g:`Er hat einen eigenen Oszillator: setze den Pin auf HIGH und er piept mit fester Tonhöhe, ganz ohne tone()-Code. Er zieht bis etwa 25–30 mA: innerhalb des absoluten Maximums von 40 mA pro Pin, aber über den meist empfohlenen 20 mA, also ist das Schalten über einen NPN-Transistor die schonendere Gewohnheit.`,xscire:`Er hat einen eigenen Oszillator: gib ihm Strom und er piept mit fester Tonhöhe. Aktive 5-V-Summer arbeiten ab etwa 3.5–4 V aufwärts, also kann ein 3.3-V-Pin keinen zuverlässig betreiben. Hier läuft er vom 5-V-V-Pin, und ein NPN-Transistor, gesteuert von GPIO 21, schaltet ihn.`,"1p7q9i9":`Ton`,"17n9x61":`≈ 2.3 kHz`,z19kz7:`Nennspannung`,"2tl42a":`5 V (funktioniert ab ≈ 3.5–4 V, je nach Hersteller)`,"1udh5u4":`≈ 25–30 mA bei 5 V`,"1xat3vm":`7.6 mm Abstand`,"1yzktex":`Polarität`,"1tmcwg9":`längerer Pin / „+“ oben = +`,i8lb7k:`10-mm-LED rot`,"513nhj":`Der Strom fließt vom langen Bein (Anode, +) zum kurzen Bein (Kathode, −, an der Abflachung des Rands). Sie braucht immer einen Widerstand in Reihe. Hier liegt sie seitlich neben der vorderen linken Ecke des Controllers und leuchtet zur linken Seite des Autos hinaus.`,"17jikfo":`Durchlassspannung`,"1g61wql":`20 mA max.`,u532rf:`220-Ω-Widerstand`,"17qhgqf":`Begrenzt den LED-Strom: (5 V − 2 V) ÷ 220 Ω ≈ 14 mA. Die Farbringe lauten rot, rot, braun: 2, 2 und × 10 = 220 Ω.`,"1kwszon":`Begrenzt den LED-Strom: (3.3 V − 2 V) ÷ 220 Ω ≈ 6 mA. Die Farbringe lauten rot, rot, braun: 2, 2 und × 10 = 220 Ω.`,zzpczz:`Ringe`,"7ytjo4":`rot · rot · braun · gold`,"1llx3uw":`Toleranz`,"3389ey":`Echo-Teiler · 1 kΩ + 2 kΩ`,i8pnlw:`Der Echo-Ausgang des HC-SR04 geht bis 5 V, aber ESP32-Pins vertragen höchstens 3.3 V. Zwei Widerstände in Reihe von Echo nach Masse bilden einen Teiler: der GPIO liest die Spannung über dem 2 kΩ, 5 V × 2 kΩ ÷ (1 kΩ + 2 kΩ) ≈ 3.3 V.`,"15yc2v4":`Ringe 1 kΩ`,"89urq0":`braun · schwarz · rot · gold`,"1ypqwgn":`Ringe 2 kΩ`,"1ywrkmt":`rot · schwarz · rot · gold`,"12k1o0e":`Echo → 1 kΩ → GPIO 35 · 2 kΩ von GPIO 35 nach G`,aarp77:`Gebraucht für`,"15e8vss":`nur ESP32`,"1aqlq1n":`Summer-Transistor · NPN + 1 kΩ`,vudz42:`Ein NPN-Transistor arbeitet als Schalter: ein kleiner Strom in seine Basis lässt einen größeren vom Kollektor zum Emitter fließen. GPIO 21 steuert die Basis über 1 kΩ, (3.3 V − 0.7 V) ÷ 1 kΩ ≈ 2.6 mA, mehr als genug, um die ≈ 30 mA des Summers vom 5-V-Pin zu schalten.`,"1gy1kba":`Transistor`,"62rwh2":`PN2222A, S8050 oder ein ähnlicher NPN`,"1tlwyig":`Kollektor`,"18vf2cp":`Summer −`,"19phq7s":`Basis`,hrttng:`1 kΩ → S von GPIO 21`,"10ztoj1":`Emitter`,"1m0unsb":`G von GPIO 21`,"16l0jzg":`Beine`,v4q23:`Pinbelegung im Datenblatt prüfen`,gy95h:`Schaltdraht`,"170hkbj":`Roter und schwarzer Litzendraht für die Motorkabel. Schneide ihn unterwegs auf Länge.`,"19d4ccc":`Rot`,ch832v:`die Lasche näher zur Mitte des Autos, an jedem Motor`,bxogn8:`Schwarz`,"1xdely8":`die Lasche näher zum Rad`,"114bxvb":`Jumperkabel Buchse–Buchse`,tq3ghm:`Dupont-Kabel mit einer Buchse an beiden Enden, die auf Stiftleisten im Raster 2.54 mm gesteckt werden. Die Treibereingänge und der Sensor nehmen ein ganzes Jumperkabel pro Pin. In zwei Hälften geschnitten, ergibt ein Jumperkabel Kabel mit einer Buchse an einem Ende: für die gelöteten Teile (die LED, der Summer) und für die Versorgung des Treibers, deren andere Enden unter die Schrauben des Steckers gehen.`,xe6ekx:`Raster`,terfe0:`15 cm (20 cm gehen auch: sie lassen größere Schlaufen)`,q9r4h7:`Ganz verwendet`,"16oowgw":`8: vier Treibereingänge, vier Sensorpins`,"1rf1gzr":`7: vier Treibereingänge, drei Sensorpins`,onu7hf:`Zerschnitten`,"38aacf":`4: ein rotes und ein schwarzes halbiert für die Kabel von LED und Summer, ein rotes und ein schwarzes 12.5 cm von einem Ende für die Versorgung des Treibers`,"3iidc0":`6: ein rotes und ein schwarzes halbiert für die Kabel von LED und Summer, ein orangefarbenes halbiert für die Basis des Transistors, ein rotes und ein schwarzes 11 cm von einem Ende für die Versorgung des Treibers, und das Echo-Kabel des Sensors für seinen Teiler`,"14fe75h":`Jumperkabel · Ultraschallsensor`,f96u6l:`Vier Jumperkabel von der Stiftleiste des Sensors, die oben ist, im Bogen zurück zum Shield. Für VCC und GND tut es jeder V- und jeder G-Pin: die nächstgelegenen werden genommen, sodass die vier Kabel nebeneinander auffächern.`,tuihok:`Vier Kabel von der Stiftleiste des Sensors, die oben ist, im Bogen zurück zum Erweiterungsboard. Echo ist ein 5-V-Signal, also geht es durch einen 1 kΩ / 2 kΩ-Teiler (in sein Jumperkabel gelötet, unter Schrumpfschlauch), bevor es den GPIO mit 3.3 V erreicht.`,ftyyiy:`V von D4`,"1xuokt7":`Trig`,o3rtpx:`S von D4`,gi87tw:`Echo`,m5ulv4:`S von D3`,y9urxb:`G von D2`,"1n4125d":`V von GPIO 32 (auf 5 V gestellt)`,p5iwlb:`S von GPIO 32`,"1aj3mnm":`1 kΩ → S von GPIO 35 · 2 kΩ von dort zu seinem G`,p0bbcd:`G von GPIO 34`,"1kn37ri":`Jumperkabel · Motortreiber`,oiporr:`Die vier Treibereingänge. Jedes Paar steuert eine Seite des Autos: IA trägt ihr Tempo, auf einem PWM-Pin, und IB ihre Richtung.`,z48w8g:`Die vier Treibereingänge, jeder auf einem PWM-fähigen Pin. Jedes Paar steuert eine Seite des Autos.`,"11ubulz":`A-IA / A-IB (links)`,jf4uze:`B-IA / B-IB (rechts)`,"15oeqsr":`Servokabel`,wowqjs:`Das eigene dreiadrige Kabel des Servos. Es geht durch den Ausschnitt nach unten und durch den Schlitz daneben wieder nach oben, zurück entlang der Platte neben dem Controller und auf die hintere Stiftleiste; was übrig ist, wird unter die Platte gefaltet. Sein 3-poliger Stecker passt auf einmal auf eine G / V / S-Stiftleiste: Braun auf G.`,v89fad:`Das eigene dreiadrige Kabel des Servos. Es geht durch den Ausschnitt nach unten und durch den Schlitz daneben wieder nach oben, zurück entlang der Platte neben dem Controller und auf die hintere Stiftleiste; was übrig ist, wird unter die Platte gefaltet. Sein 3-poliger Stecker passt auf einmal auf eine G / V / S-Stiftleiste: Braun auf G. Die V-Reihe muss auf 5 V stehen.`,r6nyn:`Braun`,"1u2gqme":`Orange (Signal)`,"1qoi1mz":`S von A5`,ovg5ed:`S von GPIO 23`,"1uovlnp":`LED-Kabel`,"1mffxae":`Ein halbes rotes und ein halbes schwarzes Jumperkabel, an die LED gelötet, mit einer Buchse am anderen Ende. Die Anode geht über den 220-Ω-Widerstand an einen Signalpin; die Kathode an Masse.`,elp8sy:`Anode (über 220 Ω)`,k62hvj:`S von D13`,ilk009:`Kathode`,k48vv7:`G von D13`,tbj8zu:`S von GPIO 13`,imqrdy:`G von GPIO 13`,"1indwkw":`Summerkabel`,"1c2cbqo":`Ein halbes rotes und ein halbes schwarzes Jumperkabel, an die Pins des Summers gelötet. Setze das +-Kabel auf HIGH, damit er piept.`,epsmo4:`Der Summer sitzt zwischen dem 5-V-V-Pin und dem Transistor. Setze GPIO 21 auf HIGH und der Transistor verbindet das − des Summers mit Masse, sodass er piept.`,"1rigupw":`S von A0`,"1yvwce0":`G von A0`,"1tndblu":`V von GPIO 21 (5 V)`,i73cl5:`Kollektor des Transistors`,a4pty4:`Basis (über 1 kΩ)`,obgy0f:`S von GPIO 21`,g663eg:`Stromverkabelung`,wp3j1m:`Alles trifft sich an einem DC-Stecker mit zwei Schraubklemmen, gesteckt in die DC-Buchse des UNO. Batterie + erreicht seine +-Klemme über den Schalter; Batterie − geht direkt an seine −-Klemme. Ein zweites rotes und ein zweites schwarzes Kabel unter denselben beiden Schrauben bringen die Batteriespannung an die VCC- und GND-Pins des Treibers. Der Treiber kann nicht stattdessen von den 5-V-Pins des Shields versorgt werden: die speist der Regler des UNO, der höchstens einige hundert mA schafft.`,"1gazt2h":`Alles trifft sich an einem DC-Stecker mit zwei Schraubklemmen, gesteckt in die DC-Buchse des Erweiterungsboards. Batterie + erreicht seine +-Klemme über den Schalter; Batterie − geht direkt an seine −-Klemme. Ein zweites rotes und ein zweites schwarzes Kabel unter denselben beiden Schrauben bringen die Batteriespannung an die VCC- und GND-Pins des Treibers. Der Treiber kann nicht stattdessen von den 5-V-Pins des Boards versorgt werden: die speist sein Regler, der höchstens einige hundert mA schafft.`,"1wuyp3l":`Batterie + (geschaltet)`,"161fdmk":`Batterie − = GND`,"6j9255":`Stecker`,"1qkac6a":`Hohlstecker 5.5 × 2.1 mm, Mitte +, mit Schraubklemmen`,"1s864ea":`Unter jeder Schraube`,wj14kx:`zwei Kabel: eines von der Batterie, eines zum Treiber`,oz5l6a:`Hindernisvermeider`,zj0mwn:`Abstand messen`,"9jogsy":`Bei jedem Durchlauf von loop() wird der Sensor angepingt. Der Sketch merkt sich auch, wann sich der Messwert zuletzt um mehr als {changeCm} cm geändert hat: ein Messwert, der gleich bleibt, während die Räder schieben, verrät ihm, dass das Auto festsitzt.`,"1va2b8a":`Weg frei?`,yssn5p:`Ist der Weg frei?`,zou1hc:`Frei heißt: nichts näher als {stopCm} cm (STOP_CM), und ein Messwert, der sich noch ändert. Dann fährt das Auto weiter und fragt {pingMs} ms später erneut.`,"164owbk":`Weiterfahren`,"2guryp":`LED aus, beide Seiten vorwärts mit CRUISE und {pingMs} ms warten: so lange braucht der Sensor zwischen zwei Pings. Dann wieder von vorn.`,l1vybm:`Stopp
LED an · Piepton`,ywa890:`Stopp, LED an, ein kurzer Piepton`,"17krb65":`Blockiert oder festgefahren: die Motoren halten an, die LED geht an und der Summer ertönt {beepMs} ms lang.`,"1njcbjw":`Festgefahren?`,"6b9vj0":`An etwas hängen geblieben, das der Strahl verfehlt hat?`,"12aymoo":`Der Strahl des Sensors ist nur etwa 15° breit, also kann das Auto an einer Ecke hängen bleiben, die es nie gesehen hat. Hat sich der Messwert {stuckMsS} lang um nicht mehr als {changeCm} cm geändert, obwohl der Weg frei aussah, sitzt das Auto fest. (Gar kein Echo, 400, zählt nie: freier Raum ist nicht „festgefahren“.)`,"7k6lib":`Zurücksetzen`,ooiwv8:`Es setzt {backOffMsS} lang von dem zurück, was es festhält, und schaut sich erst dann um.`,"1d4sv1w":`Nach rechts, dann nach links schauen`,"18crqcc":`Der Kopf dreht sich auf {lookRight}° (rechts) und auf {lookLeft}° (links). Jedes Mal bekommt der Servo {settleMsS} Zeit, dort anzukommen, bevor der Sensor gelesen wird; beide Messwerte werden ausgegeben.`,"1r9o4nf":`Ist Platz zum Drehen?`,"122yr22":`Hat keine Seite {tightCm} cm (TIGHT_CM), ist hier kein Platz zum Drehen.`,"1i7u6tc":`Zurückfahren, erneut schauen`,"1ik4v71":`Zurückfahren und erneut schauen`,a0a741:`Eingekesselt: es fährt {backMsS} lang zurück und schaut von dort aus wieder nach rechts und links, so oft wie nötig.`,"1yfjvg4":`Gerade gedreht?`,"2jbjim":`Direkt nach einer Drehung wieder blockiert?`,"3dv25u":`Der Kopf kehrt in die Mitte zurück. Dann: endete die letzte Drehung vor weniger als {againMsS}, hat sich das Auto seit der Drehung kaum bewegt.`,"1steplx":`Wieder dieselbe Richtung`,kn4k3y:`Wieder in dieselbe Richtung drehen`,"1k7wpmb":`Zurückzudrehen brächte es nur dorthin, wo es war: in einer Ecke würde es ewig links, rechts, links drehen. Also dreht es weiter in die Richtung, in die es zuletzt gedreht hat, egal was die beiden Messwerte sagen.`,"1lf2d81":`Die Seite mit mehr Platz`,"1u19y2l":`Zur Seite mit mehr Platz drehen`,"1n1zre5":`Links, wenn der Messwert links mindestens so groß ist wie der rechts, sonst rechts.`,"5j8yhm":`Drehen`,"4h9f4g":`Die beiden Seiten laufen TURN_MS lang gegeneinander ({turnMs} ms, etwa eine Vierteldrehung: stimme es auf deinen Boden ab). Dann hält das Auto an, merkt sich, in welche Richtung und wann es gedreht hat, und loop() beginnt wieder von oben.`,mz8bk9:`Auto-Modus`,rg9t88:`Zehnmal pro Sekunde pingt loop() den Sensor an und speichert den Messwert in distance (er geht gleichzeitig an RoboKit). Im Auto-Modus entscheidet dann autoStep(), was damit geschieht.`,"15ai7e9":`Blockiert heißt: etwas näher als {stopCm} cm (STOP_CM). Der Messwert kann bis zu {sampleMsS} alt sein, daher wartet es direkt nach einer Drehung {freshMs} ms auf einen, der in der neuen Richtung gemessen wurde. Sonst fährt das Auto weiter.`,"1wwbbaz":`Während es fährt, ist dir "forward": das Ende von loop() macht daraus die beiden Motordrehzahlen, mit dem Tempo, das RoboKit eingestellt hat.`,q8ujdx:`Der Strahl des Sensors ist nur etwa 15° breit, also kann das Auto an einer Ecke hängen bleiben, die es nie gesehen hat. Hat sich der Messwert während der Fahrt {stuckMsS} lang um nicht mehr als {changeCm} cm geändert, sitzt das Auto fest: es setzt zurück, bevor es sich umschaut. (Gar kein Echo, 400, zählt nie: freier Raum ist nicht „festgefahren“.)`,"1e83w8t":`Der Kopf dreht sich auf {lookRight}° (rechts), dann auf {lookLeft}° (links). Jeder Messwert wird genommen, sobald der Servo Zeit hatte, dort anzukommen, und der Kopf kehrt in die Mitte zurück.`,"1pjappa":`Endete die letzte Drehung vor weniger als {againMsS}, hat sich das Auto seit der Drehung kaum bewegt. (Auto einzuschalten beginnt von vorn: turnedAt ist dann 0.)`,pjp20w:`Zurückzudrehen brächte es nur dorthin, wo es war: in einer Ecke würde es ewig links, rechts, links drehen. Also bleibt goLeft, wie es ist, und das Auto dreht in die Richtung, in die es zuletzt gedreht hat, egal was die beiden Messwerte sagen.`,ihilws:`Die beiden Seiten laufen TURN_MS lang gegeneinander ({turnMs} ms, etwa eine Vierteldrehung: stimme es auf deinen Boden ab). Dann geht die LED aus, die Zeit wird notiert und das Auto fährt wieder.`,"1k1y69x":`4× TT-Motor`,"15bpusl":`8× Motorhalter`,dgwrs0:`M3-Bolzen, Muttern, Schrauben`,"1mkf3n0":`4× Rad, 65 mm`,"19aemsl":`L9110S-Treiber`,"123jzux":`Schaumstoffpad`,a4iz5j:`ESP32-Erweiterungsboard`,"1al7iyf":`Sensorhalter`,a89ttz:`SG90-Servo`,"1alynuo":`Servohorn`,"1pbblc6":`2 × 18650-Halter`,muur5i:`2× 18650-Zelle`,"1t10ooq":`Netzschalter`,"7h9qib":`aktiver Summer`,"1uw5qdo":`DC-Stecker`,"1l9u4j2":`16× M3-Abstandsbolzen`,hiufn9:`Schaltdraht`,"1w4hkux":`20× Jumperkabel (B–B, 15 cm)`,"1onzquf":`untere Platte`,"1h4bzq9":`mittlere Platte`,myp2cd:`obere Platte`,pu413r:`Browser blockieren ws:// auf einer Seite über https:// — starte RoboKit auf deinem Computer (npm run dev), um das Auto zu erreichen`,tqkecz:`Diese Seite wird über https ausgeliefert, daher lässt der Browser sie kein ws:// zum Auto öffnen. Um das echte Auto zu fahren, starte RoboKit auf deinem Computer (npm install, dann npm run dev) und öffne http://localhost:5173.`,vqmrol:`Dein Computer muss im Netzwerk „RoboKit“ sein, und RoboKit muss über http:// geöffnet sein, nicht über https://: Browser blockieren ws:// von sicheren Seiten, daher kann eine gehostete Kopie das Auto nicht erreichen. Starte es auf deinem Computer (npm install, solange du noch Internet hast, dann npm run dev) und öffne http://localhost:5173.`};export{e as default};